{
  "name": "pg_query",
  "description": "Run read-only SQL. The database is chosen from the schema in the query (or pass db). Always use WHERE and LIMIT. Returns a preview plus `view`, a link to the full result as an interactive table (shown to the user inline). Mention the link.",
  "group": "pg",
  "origin": "built-in",
  "execution": {
    "protocol": "dt.tool/v1",
    "transport": "in-process"
  },
  "inputSchema": {
    "type": "object",
    "properties": {
      "sql": {
        "type": "string",
        "description": "SQL"
      },
      "env": {
        "type": "string",
        "enum": [
          "dev"
        ],
        "default": "dev",
        "description": "Environment"
      },
      "db": {
        "type": "string",
        "description": "Database name from envs.json (optional)"
      },
      "params": {
        "type": "array",
        "items": {},
        "description": "Bound values for $1, $2, ... placeholders (recommended for repeatable experiments)"
      },
      "limit": {
        "type": "integer",
        "description": "Rows in the preview",
        "default": 10
      },
      "all": {
        "type": "boolean",
        "default": false,
        "description": "Return every row (up to 10000) instead of a preview: for scripts that compare or process them"
      }
    },
    "required": [
      "sql"
    ]
  }
}
